//! Departure obstacle environment of an aerodrome (CAT.POL.A.210, CS 25.115).
//!
//! The curated aerodromes carry one [`DepartureSurvey`] per direction of
//! their longest runway, generated by `tools/airport_obstacles.cjs` from
//! public data (terrain tiles, the FAA Digital Obstacle File, OpenStreetMap
//! tall structures); see the `source` block of
//! `data/airport_obstacles.json` for the provenance and the limitation: it
//! is not an AIP Type A obstacle chart. A hand-entered aerodrome carries
//! its own surveys or none, and none means the obstacle check cannot be
//! made.
//!
//! Frame: `s` is the distance along the runway heading from the start of the
//! take-off roll, `y` the offset to the right of the extended centreline,
//! both in metres; elevations are metres above mean sea level.

use std::borrow::Cow;
use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

const OBSTACLES_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/data/airport_obstacles.json"
));

/// One discrete obstacle (mast, chimney, building, crane).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DepartureObstacle {
    /// Distance from the start of the take-off roll along the runway
    /// heading, m.
    pub s_m: f64,
    /// Farthest distance of the members of a merged obstacle, m; `None` for a
    /// single object. A merged obstacle spans `s_m ..= s_max_m` at the height of
    /// its highest member, so a check reads the net path over the whole range.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub s_max_m: Option<f64>,
    /// Offset to the right of the extended centreline, m.
    pub y_m: f64,
    /// Elevation of the top above mean sea level, m.
    pub top_m: f64,
    /// Kind of obstacle as the source labels it.
    #[serde(default)]
    pub kind: String,
    /// Source record.
    #[serde(default)]
    pub source: String,
}

/// The obstacle environment of one runway direction.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DepartureSurvey {
    /// Runway designator of the direction of take-off.
    pub runway: String,
    /// True heading of the take-off direction, degrees.
    pub heading_deg: f64,
    /// Ground elevation at the end of the take-off distance in the datum of
    /// the terrain data, m; when absent the aerodrome elevation is used.
    #[serde(default)]
    pub reference_elevation_m: Option<f64>,
    /// Terrain dataset the grid comes from, as the survey generator records it.
    #[serde(default)]
    pub terrain_source: String,
    /// SYMMETRIC vertical uncertainty of a terrain-minus-reference difference, m
    /// (the dataset's own published accuracy as LE90, combined for a difference,
    /// plus the 0.1 m quantisation); `None` takes the worst dataset in use (SRTM
    /// class). It widens both the "clears" and the "violated" tests. It is the only
    /// uncertainty the requirement carries: every figure in it is a published
    /// accuracy statement of the dataset (EU-DEM v1.1: +-7 m RMSE, EEA SDI catalogue
    /// record, x 1.645 for LE90).
    #[serde(default)]
    pub vertical_uncertainty_m: Option<f64>,
    /// UNVERIFIED-SURVEY allowance, m: what can only make the true ground or object
    /// higher than the dataset reads (mobile objects on a surface the terrain data
    /// omits, 14 CFR 77.9(c); the sampling of a footprint maximum, measured at one
    /// aerodrome). A diagnostic: no regulation prints an allowance for incomplete
    /// obstacle data (CAT.POL.A.210 and AMC1-3, EASA Easy Access Rules for Air
    /// Operations, Mar. 2026, pp. 1129-1132), so it is reported beside the verdict
    /// and never added to the margin the requirement needs. `None` is zero.
    #[serde(default)]
    pub one_sided_bias_m: Option<f64>,
    /// UNVERIFIED-SURVEY completeness allowance, m: the height of trees and
    /// buildings the data may omit (a bare-earth terrain model has no vegetation or
    /// buildings without a height tag). A diagnostic like [`Self::one_sided_bias_m`],
    /// never part of the requirement. `None` is zero: a survey that attests
    /// completeness (an AIP Type A chart) states none.
    #[serde(default)]
    pub completeness_allowance_m: Option<f64>,
    /// Reference elevation less the published aerodrome elevation, m: where
    /// the terrain tile reads the aerodrome off its published elevation (RJTT: the tile reads
    /// the reclaimed runway as sea) it shows here. The check corrects its reference by it
    /// (beyond 2 m); it is not added to the uncertainty.
    #[serde(default)]
    pub reference_minus_aerodrome_elevation_m: Option<f64>,
    /// Along-track distance of the first terrain row, m.
    pub terrain_s0_m: f64,
    /// Highest ground elevation (m AMSL) of each terrain cell: rows follow
    /// the along-track cells, columns [`Self::lateral_centres_m`].
    #[serde(default)]
    pub terrain_max_elevation_m: Vec<Vec<f64>>,
    /// Along-track length of a terrain cell, m.
    #[serde(default = "default_cell_along")]
    pub cell_along_m: f64,
    /// Lateral cell centres, m.
    #[serde(default)]
    pub lateral_centres_m: Vec<f64>,
    /// Lateral width of a terrain cell, m.
    #[serde(default = "default_cell_lateral")]
    pub cell_lateral_m: f64,
    /// Discrete obstacles.
    #[serde(default)]
    pub obstacles: Vec<DepartureObstacle>,
    /// Where the survey comes from.
    #[serde(default)]
    pub provenance: String,
}

fn default_cell_along() -> f64 {
    250.0
}

fn default_cell_lateral() -> f64 {
    150.0
}

#[derive(Deserialize)]
struct Source {
    cell_along_m: f64,
    cell_lateral_m: f64,
    lateral_centres_m: Vec<f64>,
    terrain: String,
    other_obstacles: String,
    us_obstacles: String,
    limitation: String,
}

#[derive(Deserialize)]
struct AirportEntry {
    icao: String,
    directions: Vec<DepartureSurvey>,
}

#[derive(Deserialize)]
struct Table {
    source: Source,
    airports: Vec<AirportEntry>,
}

fn table() -> &'static [(String, Vec<DepartureSurvey>)] {
    static TABLE: OnceLock<Vec<(String, Vec<DepartureSurvey>)>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let parsed: Table = match serde_json::from_str(OBSTACLES_JSON) {
            Ok(parsed) => parsed,
            Err(error) => {
                tracing::error!(%error, "crates/alas-config/data/airport_obstacles.json failed to parse");
                return Vec::new();
            }
        };
        let source = parsed.source;
        let provenance = format!(
            "{}; discrete obstacles: {} (US), {} (elsewhere); {}",
            source.terrain, source.us_obstacles, source.other_obstacles, source.limitation
        );
        parsed
            .airports
            .into_iter()
            .map(|entry| {
                let surveys = entry
                    .directions
                    .into_iter()
                    .map(|mut survey| {
                        survey.cell_along_m = source.cell_along_m;
                        survey.cell_lateral_m = source.cell_lateral_m;
                        survey.lateral_centres_m = source.lateral_centres_m.clone();
                        survey.provenance = provenance.clone();
                        survey
                    })
                    .collect();
                (entry.icao, surveys)
            })
            .collect()
    })
}

/// The departure surveys of the aerodrome with this ICAO code: the curated
/// table first, then a registered custom aerodrome's own. `None` when no
/// survey exists, which the obstacle check treats as a failed check.
pub fn departure_surveys(icao: &str) -> Option<Cow<'static, [DepartureSurvey]>> {
    if let Some((_, surveys)) = table().iter().find(|(code, _)| code == icao) {
        return Some(Cow::Borrowed(surveys.as_slice()));
    }
    crate::airport_io::find_custom(icao)
        .map(|custom| custom.departure_surveys)
        .filter(|surveys| !surveys.is_empty())
        .map(Cow::Owned)
}

// A test asserts on values it built here, so a failed unwrap is the assertion failing.
#[allow(clippy::unwrap_used, clippy::expect_used)]
#[cfg(test)]
mod tests {
    use super::*;

    /// Directions the AIP declares not available for take-off, per aerodrome, as the
    /// generator records them (`takeoff_not_available`).
    fn not_available(icao: &str) -> Vec<String> {
        let table: serde_json::Value = serde_json::from_str(OBSTACLES_JSON).unwrap();
        table["airports"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|entry| entry["icao"] == icao)
            .flat_map(|entry| {
                entry["takeoff_not_available"]
                    .as_array()
                    .cloned()
                    .unwrap_or_default()
            })
            .map(|direction| direction["runway"].as_str().unwrap().to_owned())
            .collect()
    }

    /// The generator records the unverified-survey allowances in the data: the
    /// mobile-object allowance (14 CFR 77.9(c), 23 ft) and the 100 m completeness
    /// allowance (no source here bounds the objects it omits). They are diagnostics of
    /// an unverified survey and are not part of the margin the requirement needs. A
    /// direction the AIP declares not available for take-off is not surveyed (LEMD 18R,
    /// AIP Spain AD 2 LEMD AOC 3).
    #[test]
    fn the_surveys_carry_the_generator_rules() {
        const MOBILE_OBJECT_M: f64 = 23.0 * 0.3048;
        for airport in crate::airports::database() {
            for survey in departure_surveys(&airport.icao).unwrap().iter() {
                assert!(
                    survey
                        .one_sided_bias_m
                        .is_some_and(|bias| bias >= MOBILE_OBJECT_M - 0.01),
                    "{} {}: mobile-object allowance",
                    airport.icao,
                    survey.runway
                );
                assert!(
                    survey.completeness_allowance_m.is_some_and(|c| c >= 100.0),
                    "{} {}: completeness allowance",
                    airport.icao,
                    survey.runway
                );
                assert!(!not_available(&airport.icao).contains(&survey.runway));
            }
        }
        assert_eq!(not_available("LEMD"), ["18R"]);
        let lemd = departure_surveys("LEMD").unwrap();
        assert_eq!(lemd.len(), 1);
        assert_eq!(lemd[0].runway, "36L");
    }

    #[test]
    fn every_curated_aerodrome_has_surveys_for_both_directions() {
        for airport in crate::airports::database() {
            let surveys = departure_surveys(&airport.icao)
                .unwrap_or_else(|| panic!("{}: no departure survey", airport.icao));
            assert_eq!(
                surveys.len() + not_available(&airport.icao).len(),
                2,
                "{}: two directions expected, surveyed or declared not available",
                airport.icao
            );
            for survey in surveys.iter() {
                assert!(
                    !survey.terrain_max_elevation_m.is_empty(),
                    "{}",
                    airport.icao
                );
                assert!(survey
                    .terrain_max_elevation_m
                    .iter()
                    .all(|row| row.len() == survey.lateral_centres_m.len()));
                assert!(survey.terrain_s0_m <= airport.toda_m);
                assert!(
                    survey.vertical_uncertainty_m.is_some_and(|u| u > 0.0)
                        && !survey.terrain_source.is_empty(),
                    "{}: the terrain source and its uncertainty are recorded",
                    airport.icao
                );
                assert!(
                    survey.reference_minus_aerodrome_elevation_m.is_some(),
                    "{}: the datum offset is recorded",
                    airport.icao
                );
            }
        }
    }

    #[test]
    fn a_registered_aerodrome_carries_its_own_surveys() {
        use crate::airport_io::{register_custom_airport, AirportProvenance, CustomAirport};
        let _registry = crate::airport_io::REGISTRY_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let survey = DepartureSurvey {
            runway: "09".to_owned(),
            heading_deg: 90.0,
            reference_elevation_m: Some(10.0),
            terrain_source: "test".to_owned(),
            vertical_uncertainty_m: Some(0.3),
            one_sided_bias_m: None,
            completeness_allowance_m: None,
            reference_minus_aerodrome_elevation_m: Some(0.0),
            terrain_s0_m: 2000.0,
            terrain_max_elevation_m: vec![vec![12.0]],
            cell_along_m: 250.0,
            lateral_centres_m: vec![0.0],
            cell_lateral_m: 150.0,
            obstacles: Vec::new(),
            provenance: "test".to_owned(),
        };
        let mut airport = CustomAirport {
            icao: "ZSV1".to_owned(),
            name: "Survey test field".to_owned(),
            latitude_deg: 10.0,
            longitude_deg: 10.0,
            isa_delta_c: 0.0,
            altitude_m: 10.0,
            runway_lengths_m: vec![2500.0],
            declared_toda_m: None,
            declared_lda_m: None,
            departure_surveys: vec![survey.clone()],
            provenance: AirportProvenance::default(),
        };
        register_custom_airport(airport.clone()).unwrap();
        assert_eq!(departure_surveys("ZSV1").unwrap().as_ref(), &[survey]);
        airport.icao = "ZSV2".to_owned();
        airport.name = "No survey test field".to_owned();
        airport.departure_surveys.clear();
        register_custom_airport(airport).unwrap();
        assert!(departure_surveys("ZSV2").is_none());
    }

    #[test]
    fn an_unknown_aerodrome_has_no_survey() {
        assert!(departure_surveys("ZZZZ").is_none());
        assert!(departure_surveys("CUST").is_none());
    }
}
